// Cliente MapLibre + PMTiles
import maplibregl from "maplibre-gl";
import * as pmtiles from "pmtiles";

const protocol = new pmtiles.Protocol();
maplibregl.addProtocol("pmtiles", protocol.tile);

const map = new maplibregl.Map({
  container: "map",
  style: {
    version: 8,
    sources: {
      brasil: {
        type: "vector",
        url: "pmtiles://https://tiles.exemplo.com/brasil.pmtiles",
      },
    },
    layers: [
      { id: "bg", type: "background", paint: { "background-color": "#0b0d10" } },
      {
        id: "estados",
        type: "line",
        source: "brasil",
        "source-layer": "estados",
        paint: { "line-color": "#84cc16", "line-width": 1 },
      },
    ],
  },
  center: [-46.6, -23.5],
  zoom: 6,
});
